extends SceneTree

var frames := 0

func _initialize() -> void:
	var scene = load("res://main.tscn").instantiate()
	root.add_child(scene)

func _process(_delta: float) -> bool:
	frames += 1
	if frames == 20:
		var img := root.get_texture().get_image()
		if img != null:
			img.save_png("res://shot.png")
			print("SAVED ", img.get_size())
		else:
			print("NO IMAGE")
		quit()
	return false
EOF
timeout 30 godot --path . --script res://shot.gd --resolution 1280x720 2>&1 | tail -20; ls -la shot.png 2>/dev/null

