var scene
var frames=0
func _initialize(): scene=load(...).instantiate(); root.add_child(scene)
func _process(delta):
  frames+=1
  if frames==10: scene._start_scenario(0)
  if frames==20: save("intro.png")
  if frames==22: scene._show_game()
  if frames==35: save("game.png"); quit()
  return false
```
